// Error Trigger ส่งมา 1 item ต่อ 1 execution ที่พังเสมอ — $input.first() ปลอดภัย
// (ไม่เข้าเคส multi-item drop เพราะ trigger ชนิดนี้มี event เดียวต่อการ fire)
const e = $input.first().json;
const wfName = (e.workflow && e.workflow.name) || 'ไม่ทราบชื่อ workflow';
const exec = e.execution || {};
const err = exec.error || {};
const nodeName = (err.node && err.node.name) || exec.lastNodeExecuted || '-';
const message = err.message || 'ไม่มีรายละเอียด error';
const execId = exec.id || '-';
const mode = exec.mode || '-';

let content = '🚨 ระบบพัง: workflow "' + wfName + '"'
  + '\nnode: ' + nodeName
  + '\nerror: ' + message
  + '\nexecution: ' + execId + ' (' + mode + ')'
  + (exec.url ? ('\n' + exec.url) : '');

// กัน error message ยาวผิดปกติเกินลิมิต Discord 2000 ตัวอักษร
if (content.length > 1900) content = content.slice(0, 1900) + '…';

return [{ json: { content } }];
